// AI-USAGE SUMMARY
// Tools: Claude Code
// Overall AI Contribution: ~60% (framework/tool generated by `migrate-mongo init`, converted to ESM and env-driven)
// AI-Assisted Areas: ESM conversion, env variable wiring
// Human Contributions: pending team review (original CommonJS version by the team)
// Notes: Generated from SDD v0.1, SPPP, NFR doc, Sprint 1 backlog. Must be reviewed and tested by the owning team member before merge.
//
// Migrations run at deploy time (`npm run migrate`), never at application boot (architecture review F3/F6).
// Locally, docker-compose runs them when the backend container starts.

import 'dotenv/config';

const uri = process.env.MONGODB_URI;
if (!uri) {
  throw new Error('MONGODB_URI is required to run migrations (see .env.example)');
}

// migrate-mongo wants url + databaseName separately; the database name is taken from the URI path.
// Not `new URL()`: multi-host replica-set URIs (mongodb://h1,h2/db) are not WHATWG-parseable.
const dbName = (/^mongodb(?:\+srv)?:\/\/[^/]+\/([^?]*)/.exec(uri)?.[1] ?? '') || 'safedrop';

const config = {
  mongodb: {
    url: uri,
    databaseName: dbName,
    options: {},
  },
  migrationsDir: 'migrations',
  changelogCollectionName: 'changelog',
  lockCollectionName: 'changelog_lock',
  lockTtl: 300, // seconds; serialises concurrent `migrate up` runs (deploy hook + manual run)
  migrationFileExtension: '.js',
  useFileHash: false,
  moduleSystem: 'esm',
};

export default config;
